package main

import (
	"context"
	"database/sql"
	"errors"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib" // pgx stdlib adapter for database/sql

	"github.com/tiendv89/user-service/internal/config"
	"github.com/tiendv89/user-service/internal/httpapi"
	"github.com/tiendv89/user-service/internal/oauth"
	"github.com/tiendv89/user-service/internal/organizations"
	"github.com/tiendv89/user-service/internal/sessions"
	"github.com/tiendv89/user-service/internal/users"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatalf("config: %v", err)
	}

	ctx := context.Background()

	// pgxpool for direct pgx queries.
	pool, err := pgxpool.New(ctx, cfg.UserDBDSN)
	if err != nil {
		log.Fatalf("pgxpool: %v", err)
	}
	defer pool.Close()

	if err := pool.Ping(ctx); err != nil {
		log.Fatalf("db ping: %v", err)
	}

	// database/sql DB for scs/postgresstore.
	stdDB, err := sql.Open("pgx", cfg.UserDBDSN)
	if err != nil {
		log.Fatalf("sql.Open: %v", err)
	}
	defer stdDB.Close()

	sessionMgr := sessions.New(stdDB, cfg.SessionCookieDomain, cfg.SecureCookie)
	providers := oauth.NewProviders(oauth.Config{
		GoogleClientID:     cfg.OAuthGoogleClientID,
		GoogleClientSecret: cfg.OAuthGoogleClientSecret,
		GitHubClientID:     cfg.OAuthGitHubClientID,
		GitHubClientSecret: cfg.OAuthGitHubClientSecret,
		RedirectBaseURL:    cfg.OAuthRedirectBaseURL,
	})

	deps := &httpapi.Deps{
		Cfg:       cfg,
		DB:        pool,
		StdDB:     stdDB,
		Sessions:  sessionMgr,
		Providers: providers,
		Users:     users.New(pool),
		Orgs:      organizations.New(pool),
	}

	router := httpapi.NewWithDeps(deps)

	srv := &http.Server{
		Addr:              ":" + cfg.Port,
		Handler:           router,
		ReadHeaderTimeout: 10 * time.Second,
	}

	go func() {
		log.Printf("user-service listening on :%s", cfg.Port)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("server error: %v", err)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Fatalf("graceful shutdown failed: %v", err)
	}
	log.Println("server stopped")
}

