// cmd/seed is a one-shot tool that creates the Kitelabs organization in user_db
// and backfills workflow_db.workspaces.organization_id. It is idempotent — safe
// to re-run; subsequent runs update zero rows and report what is already set.
//
// Required env vars:
//
//	USER_DB_DSN      — Postgres DSN for user_db
//	WORKFLOW_DB_DSN  — Postgres DSN for workflow_db
//
// Run order (M1 deploy sequence):
//
//	1. Apply T2b migrations (user_db schema v001 — identity tables)
//	2. Apply T3 nullable migration (workflow_db v002 — add workspaces.organization_id nullable)
//	3. Run this seed command (cmd/seed)
//	4. Apply T3 NOT NULL migration (workflow_db v003 — add NOT NULL + FK constraint)
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

func main() {
	userDSN := os.Getenv("USER_DB_DSN")
	if userDSN == "" {
		log.Fatal("seed: USER_DB_DSN is required")
	}
	workflowDSN := os.Getenv("WORKFLOW_DB_DSN")
	if workflowDSN == "" {
		log.Fatal("seed: WORKFLOW_DB_DSN is required")
	}

	if err := run(context.Background(), userDSN, workflowDSN); err != nil {
		log.Fatalf("seed: %v", err)
	}
}

// run performs the full seed sequence. Exposed for testability.
func run(ctx context.Context, userDSN, workflowDSN string) error {
	orgID, err := seedKitelabsOrg(ctx, userDSN)
	if err != nil {
		return fmt.Errorf("seed kitelabs org: %w", err)
	}

	updated, alreadySet, err := backfillWorkspaces(ctx, workflowDSN, orgID)
	if err != nil {
		return fmt.Errorf("backfill workspaces: %w", err)
	}

	fmt.Printf("seed complete\n")
	fmt.Printf("  kitelabs org id : %s\n", orgID)
	fmt.Printf("  rows updated    : %d\n", updated)
	fmt.Printf("  rows already set: %d\n", alreadySet)

	return nil
}

// seedKitelabsOrg creates the Kitelabs organization in user_db if absent and
// returns its UUID. Idempotent.
func seedKitelabsOrg(ctx context.Context, dsn string) (uuid.UUID, error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return uuid.Nil, fmt.Errorf("connect user_db: %w", err)
	}
	defer pool.Close()

	if err := pool.Ping(ctx); err != nil {
		return uuid.Nil, fmt.Errorf("ping user_db: %w", err)
	}

	// Try to find the existing org first.
	var orgID uuid.UUID
	err = pool.QueryRow(ctx,
		`SELECT id FROM organizations WHERE slug = $1`, "kitelabs",
	).Scan(&orgID)
	if err == nil {
		log.Printf("seed: kitelabs org already exists (id=%s)", orgID)
		return orgID, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return uuid.Nil, fmt.Errorf("query org: %w", err)
	}

	// Insert new org.
	err = pool.QueryRow(ctx, `
		INSERT INTO organizations (slug, name)
		VALUES ($1, $2)
		ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
		RETURNING id`,
		"kitelabs", "Kitelabs",
	).Scan(&orgID)
	if err != nil {
		return uuid.Nil, fmt.Errorf("insert org: %w", err)
	}

	log.Printf("seed: created kitelabs org (id=%s)", orgID)
	return orgID, nil
}

// backfillWorkspaces updates workflow_db.workspaces rows where organization_id IS NULL
// to the given orgID. Returns the number of rows updated and the number already set.
func backfillWorkspaces(ctx context.Context, dsn string, orgID uuid.UUID) (updated, alreadySet int64, err error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return 0, 0, fmt.Errorf("connect workflow_db: %w", err)
	}
	defer pool.Close()

	if err := pool.Ping(ctx); err != nil {
		return 0, 0, fmt.Errorf("ping workflow_db: %w", err)
	}

	// Count rows already set (not NULL) before the update.
	err = pool.QueryRow(ctx,
		`SELECT count(*) FROM workspaces WHERE organization_id IS NOT NULL`,
	).Scan(&alreadySet)
	if err != nil {
		return 0, 0, fmt.Errorf("count already-set rows: %w", err)
	}

	// Update NULL rows.
	tag, err := pool.Exec(ctx,
		`UPDATE workspaces SET organization_id = $1 WHERE organization_id IS NULL`,
		orgID,
	)
	if err != nil {
		return 0, 0, fmt.Errorf("update workspaces: %w", err)
	}
	updated = tag.RowsAffected()

	return updated, alreadySet, nil
}

