}

// seedKitelabsOrg creates the Kitelabs organization in user_db if absent and
// returns its UUID. Idempotent.
func seedKitelabsOrg(ctx context.Context, dsn string) (uuid.UUID, error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return uuid.Nil, fmt.Errorf("connect user_db: %w", err)
	}
	defer pool.Close()

	if err := pool.Ping(ctx); err != nil {
		return uuid.Nil, fmt.Errorf("ping user_db: %w", err)
	}

	// Try to find the existing org first.
	var orgID uuid.UUID
	err = pool.QueryRow(ctx,
		`SELECT id FROM organizations WHERE slug = $1`, "kitelabs",
	).Scan(&orgID)
	if err == nil {
		log.Printf("seed: kitelabs org already exists (id=%s)", orgID)
		return orgID, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return uuid.Nil, fmt.Errorf("query org: %w", err)
	}

	// Insert new org.
	err = pool.QueryRow(ctx, `
		INSERT INTO organizations (slug, name)
		VALUES ($1, $2)
		ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name
		RETURNING id`,
		"kitelabs", "Kitelabs",
	).Scan(&orgID)
	if err != nil {
		return uuid.Nil, fmt.Errorf("insert org: %w", err)
	}

	log.Printf("seed: created kitelabs org (id=%s)", orgID)
	return orgID, nil
}

// backfillWorkspaces updates workflow_db.workspaces rows where organization_id IS NULL
// to the given orgID. Returns the number of rows updated and the number already set.
func backfillWorkspaces(ctx context.Context, dsn string, orgID uuid.UUID) (updated, alreadySet int64, err error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return 0, 0, fmt.Errorf("connect workflow_db: %w", err)
	}
	defer pool.Close()

	if err := pool.Ping(ctx); err != nil {
		return 0, 0, fmt.Errorf("ping workflow_db: %w", err)
	}

	// Count rows already set (not NULL) before the update.
	err = pool.QueryRow(ctx,
		`SELECT count(*) FROM workspaces WHERE organization_id IS NOT NULL`,
	).Scan(&alreadySet)
	if err != nil {
		return 0, 0, fmt.Errorf("count already-set rows: %w", err)
	}

	// Update NULL rows.
	tag, err := pool.Exec(ctx,
		`UPDATE workspaces SET organization_id = $1 WHERE organization_id IS NULL`,
		orgID,
	)
	if err != nil {
		return 0, 0, fmt.Errorf("update workspaces: %w", err)
	}
	updated = tag.RowsAffected()

	return updated, alreadySet, nil
}

